def hydrate_time(nanoseconds, tz=None):
    """ Hydrator for `Time` and `LocalTime` values.

    :param nanoseconds: Number of nanoseconds since the Unix epoch.
    :param tz: Optional timezone to localize the time. If None, UTC is assumed.
    :return: datetime.time instance representing the given nanoseconds.
    """
    from datetime import datetime, timezone

    # Allow None input to produce a predictable output (None or raise).
    if nanoseconds is None:
        return None

    try:
        # Convert nanoseconds to seconds as a float.
        seconds = nanoseconds / 1_000_000_000
    except Exception as exc:
        raise TypeError(f"nanoseconds must be an integer or float, got {type(nanoseconds).__name__}") from exc

    try:
        # Build a datetime object. Use UTC if no tz is supplied.
        if tz is None:
            dt = datetime.utcfromtimestamp(seconds)
        else:
            dt = datetime.fromtimestamp(seconds, tz=tz)
        # Adjust microsecond part from the nano remainder.
        micro = (nanoseconds % 1_000_000_000) // 1000
        dt = dt.replace(microsecond=micro)
        return dt.time()
    except Exception as exc:
        raise ValueError(f"Could not hydrate time from nanoseconds: {nanoseconds}") from exc

