            else:
                raise AttributeError("No suitable data source found for keys retrieval")
        return list(data_source.keys())
    except Exception as exc:
        raise RuntimeError("Could not retrieve record keys") from exc

def protocol_handlers(cls, protocol_version=None):
        """
