def data(self, *keys):
    """
    Return the keys and values of this record as a dictionary,
    optionally including only certain values by index or key. Keys
    provided in the items that are not in the record will be
    inserted with a value of :const:`None`; indexes provided
    that are out of bounds will trigger an :exc:`IndexError`.

    :param keys: indexes or keys of the items to include; if none
                      are provided, all values will be included
    :return: dictionary of values, keyed by field name
    :raises: :exc:`IndexError` if an out-of-bounds index is specified
    """
    # Ensure required attributes exist
    if not hasattr(self, "_values") or not hasattr(self, "_field_names"):
        raise AttributeError("Record object missing required '_values' or '_field_names' attributes")
    values = self._values
    names = self._field_names

    if not keys:
        return dict(zip(names, values))

    # Prepare a mapping from field names to indices for quick lookup
    try:
        name_to_index = {name: i for i, name in enumerate(names)}
    except TypeError:
        # In case _field_names is not a sequence of hashable names
        name_to_index = {}
        for i, name in enumerate(names):
            try:
                name_to_index[name] = i
            except Exception:
                continue

    result = {}
    for key in keys:
        if isinstance(key, int):
            # Treat as index
            if key < 0 or key >= len(values):
                raise IndexError(f"Index {key} out of bounds for record of length {len(values)}")
            field_name = names[key]
            result[field_name] = values[key]
        else:
            # Treat as field name
            if key in name_to_index:
                idx = name_to_index[key]
                result[key] = values[idx]
            else:
                # Insert missing key with None
                result[key] = None
    return result

