def deprecated(message):
    """ Decorator for deprecating functions and methods.

    ::

        @deprecated("'foo' has been deprecated in favour of 'bar'")
        def foo(x):
            pass

    """
    import functools
    if not isinstance(message, str):
        raise TypeError("message must be a string")
    def decorator(func):
        if not callable(func):
            raise TypeError("decorated object must be callable")
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            try:
                import warnings
                # Emit a warning only once per call site
                warnings.warn(message, DeprecationWarning, stacklevel=2)
            except Exception:
                # If warnings cannot be emitted, fall back to a silent pass
                pass
            return func(*args, **kwargs)
        # Expose a flag for introspection if needed
        wrapper.__deprecated__ = True
        wrapper.__deprecated_message__ = message
        return wrapper
    return decorator

def _inline_r_setup(code: str) -> str:
    """
    Some behaviour of R cannot be configured via env variables, but can only be configured
    via R options once R has started. These are set here.
    """
    if not isinstance(code, str):
        raise TypeError("The `code` argument must be a string.")
    # If the code is empty, nothing to do.
    if code.strip() == "":
        return code

    try:
        # Common R options that are typically set programmatically.
        # Adjust as necessary for your R environment.
        options = {
            "stringsAsFactors": False,
            "scipen": 999,
            "digits": 10,
            "warn": 2,  # Turn warnings into errors
            "max.print": 99999,
        }

        option_lines = []
        for name, value in options.items():
            if isinstance(value, str):
                val_repr = f'"{value}"'
            else:
                val_repr = str(value)
            option_lines.append(f'options({name}={val_repr})')
        # Join the option lines and prepend them to the provided R code.
        options_block = "\n".join(option_lines) + "\n\n"
        return options_block + code
    except Exception as exc:
        raise RuntimeError(f"Failed to set inline R options: {exc}") from exc

def parse_version(s: str) -> tuple[int, ...]:
    """poor man's version comparison"""
    if not isinstance(s, str):
        raise TypeError("Input must be a string")
    parts = s.strip().split('.')
    nums: list[int] = []
    for part in parts:
        if not part:
            continue
        # Take anything before a hyphen (e.g., "3-alpha" -> "3")
        stripped = part.split('-', 1)[0]
        try:
            nums.append(int(stripped))
        except ValueError:
            # Ignore parts that cannot be converted to integers
            continue
    if not nums:
        # Default to zero if nothing matched
        return (0,)
    return tuple(nums)

def ttl_cache(maxsize=128, ttl=600, timer=time.monotonic, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm with a per-item time-to-live (TTL) value.
    """
    import collections
    import functools

    if not isinstance(maxsize, int) or maxsize < 0:
        raise ValueError("maxsize must be a non‑negative integer")
    if not callable(timer):
        raise TypeError("timer must be a callable that returns a monotone float")
    if ttl < 0:
        raise ValueError("ttl must be non‑negative")

    def _make_key(args, kwargs, typed):
        key = args
        if kwargs:
            # sort kwargs to make key deterministic
            for k in sorted(kwargs):
                key += (k, kwargs[k])
        if typed:
            # include types in the key to distinguish by type
            key += tuple(type(v) for v in args)
            if kwargs:
                key += tuple(type(kwargs[k]) for k in sorted(kwargs))
        try:
            hash(key)
        except Exception as exc:
            raise TypeError(f"Unhashable key {key}") from exc
        return key

    def decorating_function(user_function):
        cache = collections.OrderedDict()
        hits = misses = 0

        @functools.wraps(user_function)
        def wrapper(*args, **kwargs):
            nonlocal hits, misses
            key = _make_key(args, kwargs, typed)
            now = timer()
            try:
                result, expire = cache[key]
            except KeyError:
                # Cache miss
                misses += 1
                result = user_function(*args, **kwargs)
                expire = now + ttl
                cache[key] = (result, expire)
                if maxsize and len(cache) > maxsize:
                    cache.popitem(last=False)
                return result
            else:
                if expire > now:
                    # Cache hit and still valid
                    hits += 1
                    cache.move_to_end(key)
                    return result
                else:
                    # Cache entry expired
                    del cache[key]
                    # Treat as miss
                    misses += 1
                    result = user_function(*args, **kwargs)
                    expire = now + ttl
                    cache[key] = (result, expire)
                    if maxsize and len(cache) > maxsize:
                        cache.popitem(last=False)
                    return result

        def cache_info():
            """Return cache statistics."""
            return collections.namedtuple('CacheInfo', ['hits', 'misses', 'maxsize', 'currsize'])(
                hits, misses, maxsize, len(cache)
            )

        def cache_clear():
            """Clear the cache and statistics."""
            nonlocal hits, misses
            cache.clear()
            hits = 0
            misses = 0

        wrapper.cache_info = cache_info
        wrapper.cache_clear = cache_clear
        return wrapper

    return decorating_function

def lfu_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Frequently Used (LFU)
    algorithm.
    """
    if not isinstance(maxsize, int) or maxsize < 0:
        raise ValueError("maxsize must be a non-negative integer")

    def decorator(func):
        cache = {}  # key -> (value, freq)

        def make_key(args, kwargs):
            """Build a hashable key from function arguments."""
            key = []
            for arg in args:
                key.append((arg, type(arg)) if typed else arg)
            # Sort keyword items to ensure consistent ordering
            for k in sorted(kwargs):
                v = kwargs[k]
                key.append((k, (v, type(v)) if typed else v))
            return tuple(key)

        def wrapper(*args, **kwargs):
            if maxsize == 0:
                # No caching; directly call the function
                return func(*args, **kwargs)

            key = make_key(args, kwargs)

            if key in cache:
                value, freq = cache[key]
                cache[key] = (value, freq + 1)
                return value

            # Compute the function result
            value = func(*args, **kwargs)

            # If cache is full, evict the least frequently used entry.
            if len(cache) >= maxsize:
                # Find key with minimal frequency
                lfu_key = min(cache.items(), key=lambda item: item[1][1])[0]
                del cache[lfu_key]

            cache[key] = (value, 1)
            return value

        return wrapper

    return decorator

def popitem(self):
    """Remove and return the `(key, value)` pair first inserted."""
    # Identify the storage dictionary
    data = getattr(self, "_data", self)
    if not isinstance(data, dict):
        raise TypeError("popitem: underlying data is not a dict")

    # Try to use an explicit key order list if available
    keys_attr = getattr(self, "_keys", None)
    if keys_attr is not None and hasattr(keys_attr, "__len__") and hasattr(keys_attr, "__getitem__"):
        try:
            key = keys_attr[0]
        except (IndexError, TypeError):
            raise KeyError("popitem from an empty dictionary")
        # Remove the key from both structures
        try:
            value = data.pop(key)
        except KeyError:
            # If the key is missing from data, drop it from the order list and retry
            keys_attr.pop(0)
            return self.popitem()
        keys_attr.pop(0)
        return key, value

    # Fallback: use dict iteration ordering (Python 3.7+ guarantees order)
    try:
        key = next(iter(data))
    except StopIteration:
        raise KeyError("popitem from an empty dictionary")
    value = data.pop(key)
    return key, value

