def extostr(cls, e, max_level=30, max_path_level=5):
        """
        Format an exception into a readable string with a truncated stack trace.
        :param e: Any exception instance.
        :type e: Exception
        :param max_level: Maximum number of traceback frames to include (default 30)
        :type max_level: int
        :param max_path_level: Maximum depth of file path components to display (default 5)
        :type max_path_level: int
        :return str: Human‑readable exception description
        """
        try:
            if e is None or not isinstance(e, BaseException):
                raise TypeError("The 'e' argument must be an Exception instance")

            import os, traceback

            # Normalise limits
            if not isinstance(max_level, int) or max_level <= 0:
                max_level = None  # show all
            if not isinstance(max_path_level, int) or max_path_level <= 0:
                max_path_level = 1

            tb = e.__traceback__
            # If no traceback, try the cause or context fallback
            if tb is None:
                tb = getattr(e, "__cause__", None) or getattr(e, "__context__", None)

            # Extract frames; if still None, we'll just rely on message
            frames = []
            if tb is not None:
                extracted = traceback.extract_tb(tb)
                frames = extracted[:max_level] if max_level is not None else extracted

            def _shrink_path(path):
                """Return a shortened version of a path, keeping at most max_path_level components."""
                parts = path.split(os.sep)
                if len(parts) <= max_path_level:
                    return path
                # keep first, last max_path_level-1
                return os.sep.join(
                    parts[:1] + ["..."] + parts[-(max_path_level-1):]
                )

            lines = [f"{type(e).__name__}: {e}"]

            if frames:
                lines.append("Traceback (most recent call last):")
                for frm in frames:
                    file_path = _shrink_path(frm.filename) if frm.filename else "<unknown>"
                    line_no = frm.lineno
                    func_name = frm.name
                    lines.append(f'  File "{file_path}", line {line_no}, in {func_name}')
                    # Include the line of code if available
                    if frm.line:
                        # strip trailing newlines and leading spaces for pretty printing
                        code = frm.line.strip()
                        if code:
                            lines.append(f'    {code}')

            return "\n".join(lines)

        except Exception:
            # Fallback: return plain string representation of the exception
            return str(e) or repr(e)

def is_file_exist(file_name):
        """
        Check if file name exist.
        :param file_name: File name.
        :type file_name: str
        :return: Return true (exist), false (do not exist, or invalid file name)
        :rtype bool
        """
        try:
            if not isinstance(file_name, str) or not file_name:
                return False
            import os
            return os.path.isfile(file_name)
        except Exception:
            return False

def namesAndDescriptions(self, all=False):  # pylint:disable=redefined-builtin
    """
    Return a mapping of attribute names to their descriptions as defined by the interface.
    If `all` is False, only attributes with non-empty descriptions are returned.
    Attributes that start with '_' are ignored. This method is tolerant of errors
    in attribute access and will skip those attributes.
    """
    descriptions = {}
    try:
        for name in dir(self):
            if name.startswith('_'):
                continue
            try:
                attr = getattr(self, name)
                desc = ''
                # Prefer the attribute's own docstring
                if hasattr(attr, '__doc__') and attr.__doc__:
                    desc = attr.__doc__
                # Fallback to the type's docstring for descriptors
                elif hasattr(type(attr), '__doc__') and type(attr).__doc__:
                    desc = type(attr).__doc__
                if not all and not desc:
                    continue
                descriptions[name] = desc
            except Exception:
                continue
    except Exception:
        return {}
    return descriptions

def _normalizeargs(sequence, output=None):
    """Normalize declaration arguments

    Normalization arguments might contain Declarations, tuples, or single
    interfaces.

    Anything but individual interfaces or implements specs will be expanded.
    """
    if sequence is None:
        return []
    if output is None:
        output = []

    for item in sequence:
        # Skip None items
        if item is None:
            continue
        # Recursive expansion for iterable containers except strings
        if isinstance(item, (tuple, list)):
            _normalizeargs(item, output)
        else:
            output.append(item)
    return output

