def reset(self):
    """
    Reset the histogram.

    Current context is reset to an empty dict.
    Bins are reinitialized with the *initial_value*
    or with *make_bins()* (depending on the initialization).
    """
    # Reset the context to an empty dictionary.
    # The attribute may be named `context` or `_context`; try both.
    context_attr_names = ("context", "_context")
    for name in context_attr_names:
        if hasattr(self, name):
            try:
                setattr(self, name, {})
            except Exception:
                # If the attribute is read‑only, ignore and continue
                pass
            break  # stop after the first successful reset

    # Reinitialize bins.
    # Prefer a stored `initial_value` over a callable `make_bins()` if both exist.
    if hasattr(self, "initial_value"):
        try:
            # If initial_value is a scalar, place it in a list; otherwise use it directly.
            val = getattr(self, "initial_value")
            bins_attr_names = ("bins", "_bins")
            for name in bins_attr_names:
                if hasattr(self, name):
                    try:
                        setattr(self, name, [val] if isinstance(val, (int, float, complex, str, bool)) else val)
                    except Exception:
                        # If assignment fails, ignore and continue
                        pass
                    break
        except Exception:
            # If accessing initial_value or setting bins fails, fall back to make_bins()
            self._reset_bins_with_make_bins()
    elif hasattr(self, "make_bins") and callable(getattr(self, "make_bins")):
        self._reset_bins_with_make_bins()
    else:
        # No known initialization method; set bins to an empty list
        bins_attr_names = ("bins", "_bins")
        for name in bins_attr_names:
            if hasattr(self, name):
                try:
                    setattr(self, name, [])
                except Exception:
                    pass

def _reset_bins_with_make_bins(self):
    """
    Helper to set bins using the make_bins() method.
    """
    try:
        bins = getattr(self, "make_bins")()
    except Exception:
        bins = []
    bins_attr_names = ("bins", "_bins")
    for name in bins_attr_names:
        if hasattr(self, name):
            try:
                setattr(self, name, bins if isinstance(bins, list) else [bins])
            except Exception:
                pass
    return None

def to_csv(self, separator=",", header=None):
    """Convert the graph's points to a CSV formatted string.

    The method is kept for backward compatibility but is
    deprecated. A header line (if provided) is added as the
    first line. For each point the coordinate components are
    joined by *separator* and each part of the value is appended
    in the same fashion. Scalars are converted directly to
    strings. ``separator`` must be a string; ``header`` is either
    a string or ``None``.  The function is tolerant of graphs
    that expose their data as an ``items`` mapping or as an
    iterable of ``(coordinate, value)`` pairs.
    """
