def integral(bins, edges):
    """Compute integral (scale for a histogram).

    *bins* contain values, and *edges* form the mesh
    for the integration.
    Their format is defined in :class:`.histogram` description.
    """
    try:
        import numpy as np
    except Exception as exc:
        raise ImportError("numpy is required for integral calculation") from exc

    # Convert inputs to NumPy arrays
    try:
        bins_arr = np.asarray(bins, dtype=float)
        edges_arr = np.asarray(edges, dtype=float)
    except Exception as exc:
        raise TypeError("bins and edges must be array-like") from exc

    # Validate dimensionality
    if bins_arr.ndim != 1 or edges_arr.ndim != 1:
        raise ValueError("bins and edges must be one‑dimensional")

    # Validate length relationship
    if len(edges_arr) != len(bins_arr) + 1:
        raise ValueError("Number of edges must be exactly one more than number of bins")

    # Compute widths and ensure they are non‑negative
    widths = edges_arr[1:] - edges_arr[:-1]
    if np.any(widths < 0):
        raise ValueError("Histogram edges must be in ascending order")

    # Compute integral
    return np.sum(bins_arr * widths)

def is_fill_request_seq(seq):
    """Test whether *seq* can be converted to a FillRequestSeq.

    True only if it is a FillRequest element
    or contains at least one such,
    and it is not a Source sequence.
    """
    try:
        if seq is None:
            return False

        # If the object itself is a FillRequest, it's valid.
        if isinstance(seq, FillRequest):
            return True

        # Source objects (or sequences of Source) should be rejected.
        if isinstance(seq, Source):
            return False

        # Attempt to iterate over seq; if not iterable, return False.
        try:
            iterator = iter(seq)
        except TypeError:
            return False

        # Look for at least one FillRequest element.
        for item in iterator:
            if isinstance(item, FillRequest):
                return True

        return False
    except Exception:
        # Any unexpected error (e.g., missing type names) results in a safe False.
        return False

