def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """
    # Basic sanity checks
    if not hasattr(app, "spec"):
        raise AttributeError("The provided application object has no 'spec' attribute.")

    spec = app.spec

    # Ensure the manifest exists and is iterable
    manifest = getattr(spec, "manifest", None)
    if manifest is None:
        # Nothing to do if there is no manifest
        return

    if not isinstance(manifest, (list, tuple)):
        raise TypeError("Expected spec.manifest to be a list or tuple of resource dictionaries.")

    # Ensure observer_schema is a dictionary to store custom and default schemas
    observer_schema = getattr(spec, "observer_schema", None)
    if observer_schema is None:
        observer_schema = {}
        spec.observer_schema = observer_schema
    elif not isinstance(observer_schema, dict):
        raise TypeError("Expected spec.observer_schema to be a dict or None, got %r." % type(observer_schema))

    # Iterate over each resource and create default schema if needed
    for idx, resource in enumerate(manifest):
        # Skip non-dict resources
        if not isinstance(resource, dict):
            continue

        kind = resource.get("kind")
        metadata = resource.get("metadata", {})
        name = None
        if isinstance(metadata, dict):
            name = metadata.get("name")

        # If either kind or name is missing, skip this resource
        if not kind or not name:
            continue

        key = f"{kind}:{name}"

        # Custom schema already provided? Skip generation
        if key in observer_schema:
            continue

        # Generate a simple default observer schema
        # For demonstration purposes this schema just declares a "status" field
        # which may be an object or null.
        default_schema = {
            "type": "object",
            "properties": {
                "status": {
                    "type": ["object", "null"]
                }
            },
            "required": ["status"]
        }

        observer_schema[key] = default_schema

def status_str(self, prefix=''):
    """Return string of validator status, with optional prefix."""
    # Normalize prefix to a string; fall back to empty string on failure.
    try:
        if prefix is None:
            prefix = ''
        else:
            prefix = str(prefix)
    except Exception:
        prefix = ''
    # Determine status message, handling missing attributes gracefully.
    try:
        # Default assumption: valid if 'is_valid' attribute is missing.
        if hasattr(self, 'is_valid'):
            is_valid = bool(getattr(self, 'is_valid'))
        else:
            is_valid = True
        if is_valid:
            status_msg = 'OK'
        else:
            # Try to obtain a helpful error message.
            if hasattr(self, 'error_msg'):
                err_msg = getattr(self, 'error_msg')
            elif hasattr(self, 'error'):
                err_msg = getattr(self, 'error')
            else:
                err_msg = 'Unknown error'
            status_msg = f'Error: {err_msg}'
    except Exception:
        status_msg = 'unknown status'
    return f'{prefix}{status_msg}'

def status_str(self, prefix=''):
    """Return string representation of validation log, with optional prefix."""
    try:
        log = getattr(self, 'validation_log', None)
        if not log:
            return ''
        # Determine how to interpret the log
        if isinstance(log, str):
            lines = log.splitlines()
        elif isinstance(log, dict):
            lines = [f"{k}: {v}" for k, v in log.items()]
        elif isinstance(log, (list, tuple, set)):
            lines = [str(item) for item in log]
        else:
            # Fallback: try to convert the whole object to string
            try:
                lines = [str(log)]
            except Exception:
                lines = []
        # Apply prefix to each line
        prefixed_lines = [f"{prefix}{line}" for line in lines]
        return '\n'.join(prefixed_lines)
    except Exception:
        return ''

def check_digests_present_and_used(self, manifest_files, digests_used):
        """Check all digests in manifest that are needed are present and used."""
        # Normalize inputs
        if not isinstance(manifest_files, (list, tuple)):
            raise TypeError(f"manifest_files must be a list or tuple, got {type(manifest_files)}")
        if not isinstance(digests_used, (set, list, tuple)):
            raise TypeError(f"digests_used must be a set, list, or tuple, got {type(digests_used)}")
        # Use lower‑case for consistent comparison
        digests_used_set = {str(d).lower() for d in digests_used}

        # Collect all digests that appear in the manifest
        manifest_digests = set()
        for idx, manifest_item in enumerate(manifest_files):
            if not isinstance(manifest_item, dict):
                raise TypeError(f"Each item in manifest_files must be a dict, "
                                f"but item {idx} is {type(manifest_item)}")
            # Assume digests are stored under a key named 'digests' or 'hashes'
            digests = None
            for key in ('digests', 'hashes', 'checksums', 'signature'):
                if key in manifest_item:
                    digests = manifest_item[key]
                    break
            if digests is None:
                continue  # No digest info to check for this item
            if isinstance(digests, dict):
                manifest_digests.update({str(k).lower() for k in digests.keys()})
            elif isinstance(digests, (list, tuple)):
                manifest_digests.update({str(d).lower() for d in digests})
            else:
                raise TypeError(f"Unexpected digest format for item {idx}: {type(digests)}")

        # Digests present in manifest but not marked as used
        unused_in_manifest = manifest_digests - digests_used_set
        # Digests marked as used but missing in manifest
        missing_in_manifest = digests_used_set - manifest_digests

        error_messages = []
        if unused_in_manifest:
            error_messages.append(
                f"Digests found in manifest but not used: {sorted(unused_in_manifest)}"
            )
        if missing_in_manifest:
            error_messages.append(
                f"Digests used but not present in manifest: {sorted(missing_in_manifest)}"
            )

        if error_messages:
            raise ValueError(" | ".join(error_messages))
        # If we reach here, all required digests are present and used properly.  ▪︎

        return None  # Explicitly return None for clarity only₫

def validate_as_prior_version(self, prior):
    """Check that prior is a valid prior version of the current inventory object.

    The input variable prior is also expected to be an InventoryValidator object
    and both self and prior inventories are assumed to have been checked for
    internal consistency.
    """
    # Ensure prior is the same type as self
    if not isinstance(prior, self.__class__):
        raise ValueError("prior must be an instance of the same validator class")

    # Verify that each object has a numeric `version` attribute
    self_version = getattr(self, "version", None)
    prior_version = getattr(prior, "version", None)
    if self_version is None or prior_version is None:
        raise ValueError("Both validator objects must expose a 'version' attribute")

    if not isinstance(self_version, (int, float)) or not isinstance(prior_version, (int, float)):
        raise ValueError("The 'version' attribute must be numeric (int or float)")

    if prior_version >= self_version:
        raise ValueError(
            f"prior.version ({prior_version}) must be less than self.version ({self_version})"
        )

    # If both objects expose an 'items' collection, ensure that prior's items are a subset
    self_items = getattr(self, "items", None)
    prior_items = getattr(prior, "items", None)

    if self_items is not None and prior_items is not None:
        try:
            if not set(prior_items).issubset(set(self_items)):
                raise ValueError(
                    "Items in prior inventory are not a subset of current inventory items"
                )
        except TypeError:
            # Items might be unhashable; fall back to list containment checks
            for item in prior_items:
                if item not in self_items:
                    raise ValueError(
                        "Items in prior inventory are not a subset of current inventory items"
                    )

    # If timestamps are available, ensure prior is older or equal to current
    self_ts = getattr(self, "created_at", None)
    prior_ts = getattr(prior, "created_at", None)
    if self_ts is not None and prior_ts is not None:
        try:
            if prior_ts > self_ts:
                raise ValueError(
                    "prior's created_at timestamp must be less than or equal to self's created_at timestamp"
                )
        except TypeError:
            # If timestamps cannot be compared, ignore this check
            pass

    # If all checks pass, validate successfully
    return True

def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    # Validate input types
    if not isinstance(inventory, dict):
        raise TypeError("inventory must be a dictionary")
    if not isinstance(version, (str, int)):
        raise TypeError("version must be a string or integer key")

    # Attempt to retrieve the version data
    try:
        version_info = inventory[version]
    except KeyError as exc:
        raise KeyError(f"Version {version!r} not found in inventory") from exc
    except Exception as exc:
        raise RuntimeError(f"Unexpected error accessing inventory: {exc}") from exc

    # Extract state mapping; fall back to empty dict if missing or malformed
    try:
        state = version_info.get('state', {})
        if not isinstance(state, dict):
            raise ValueError("state field must be a dictionary")
    except Exception as exc:
        raise ValueError(f"Invalid state format for version {version!r}: {exc}") from exc

    result = {}
    for logical_path, content in state.items():
        # Ensure logical_path is hashable
        try:
            hash(logical_path)
        except Exception as exc:
            raise ValueError(f"Logical path {logical_path!r} is unhashable: {exc}") from exc

        # Normalize content files to a set
        try:
            if isinstance(content, (set, list, tuple)):
                files = set(content)
            else:
                files = {content}
        except Exception as exc:
            # If any unexpected issue, skip this entry but log the error
            continue

        result[logical_path] = files

    return result

def files_list(path):
    """
    Return the files in `path`
    """
    import os
    # Validate that path is supplied and is a string-like object
    if path is None:
        raise TypeError("path is required and must be a string or bytes")
    if not isinstance(path, (str, bytes)):
        raise TypeError(f"path must be a string or bytes, got {type(path).__name__}")
    # Convert bytes to string if necessary
    if isinstance(path, bytes):
        try:
            path = path.decode()
        except Exception as exc:
            raise TypeError("bytes path could not be decoded to UTF-8") from exc
    # If the path does not exist, return an empty list (caller can interpret as no files)
    if not os.path.exists(path):
        return []
    # Ensure the path points to a directory
    if not os.path.isdir(path):
        raise NotADirectoryError(f"'{path}' is not a directory")
    try:
        # Use scandir for efficient file filtering
        return [entry.name for entry in os.scandir(path) if entry.is_file()]
    except OSError:
        # In case of any filesystem error return an empty list
        return []

def _explore_folder(folder):
    """
    Get packages' data from folder

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    folder : str
        Folder of the package
    Returns
    -------
    dict
    """
    # basic validation
    if not isinstance(folder, str):
        raise TypeError("folder must be a string path")
    try:
        import os
        if not os.path.isdir(folder):
            raise FileNotFoundError(f"No such directory: {folder}")
        # first pass: collect all base names of XML files
        xml_basenames = set()
        try:
            entries = os.listdir(folder)
        except OSError as e:
            raise RuntimeError(f"Error accessing directory '{folder}': {e}") from e
        for entry in entries:
            full_path = os.path.join(folder, entry)
            if os.path.isfile(full_path):
                name, ext = os.path.splitext(entry)
                if ext.lower() == ".xml":
                    xml_basenames.add(name)
        # second pass: group all files whose basename is in xml_basenames
        result = {}
        for entry in entries:
            full_path = os.path.join(folder, entry)
            if os.path.isfile(full_path):
                name, _ = os.path.splitext(entry)
                if name in xml_basenames:
                    result.setdefault(name, []).append(full_path)
        return result
    except Exception as exc:
        # re-raise as RuntimeError to indicate runtime failure
        raise RuntimeError(f"Failed to explore folder '{folder}': {exc}") from exc

