def match_pubdate(node, pubdate_xpaths):
    """
    Retorna o primeiro match da lista de pubdate_xpaths
    """
    for xpath_expr in pubdate_xpaths:
        if not xpath_expr:
            continue
        try:
            result = node.xpath(xpath_expr)
        except Exception:
            continue
        if not result:
            continue
        first_item = result[0]
        # Se for string direto
        if isinstance(first_item, str):
            return first_item.strip()
        # Se for um nó XML
        if hasattr(first_item, 'text'):
            if first_item.text:
                return first_item.text.strip()
        # Caso seja outro tipo, converta para string
        try:
            return str(first_item).strip()
        except Exception:
            continue
    return None

def pretty(self, indent=0, debug=False):
        """
        Return a pretty formatted representation of self.
        """
        def _pretty(obj, level):
            indent_str = '    ' * level
            if isinstance(obj, dict):
                items = []
                for k, v in obj.items():
                    items.append(f"\n{indent_str}    {repr(k)}: {_pretty(v, level + 1)}")
                return "{" + ",".join(items) + f"\n{indent_str}" + "}"
            elif isinstance(obj, list):
                items = []
                for v in obj:
                    items.append(f"\n{indent_str}    {_pretty(v, level + 1)}")
                return "[" + ",".join(items) + f"\n{indent_str}" + "]"
            elif isinstance(obj, tuple):
                items = []
                for v in obj:
                    items.append(f"\n{indent_str}    {_pretty(v, level + 1)}")
                return "(" + ",".join(items) + f"\n{indent_str}" + ")"
            elif isinstance(obj, set):
                if not obj:
                    return "{}"
                items = []
                for v in obj:
                    items.append(f"\n{indent_str}    {_pretty(v, level + 1)}")
                return "{" + ",".join(items) + f"\n{indent_str}" + "}"
            else:
                # For non-collection objects, just use repr
                return repr(obj)

        try:
            pretty_str = _pretty(self, indent)
        except Exception as exc:
            # In case of unexpected errors, return a safe representation
            pretty_str = f"<Error during pretty printing: {exc}>"

        if debug:
            pretty_str += f"\n# Type: {type(self).__name__}"
        return pretty_str

def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    try:
        # Copy to avoid mutating input
        processed = list(args)

        # Helper predicates if available
        def is_and(expr):
            return hasattr(expr, "is_and") and expr.is_and()

        def is_or(expr):
            return hasattr(expr, "is_or") and expr.is_or()

        def is_not(expr):
            return hasattr(expr, "is_not") and expr.is_not()

        def args_of(expr):
            return getattr(expr, "args", ())

        def not_of(expr):
            # Attempt to construct Not(expr) if class exists
            if hasattr(self, "Not"):
                return self.Not(expr)
            # Fallback: expose Not as a call
            return type(expr)(expr, negate=True)  # may raise

        # Iterate until no changes
        changed = True
        while changed:
            changed = False
            new_processed = []
            for expr in processed:
                # Simplify only if it's a conjunction or disjunction at top level
                if is_and(expr):
                    sub = list(args_of(expr))
                    # Look for absorption patterns
