def on(self, hook):
    """
    Decorator function to add a new handler to the registry.

    Args:
        hook (HookType): Hook attribute for which to register the handler.

    Returns:
        callable: Decorator for registering listeners for the specified
        hook.
    """
    # Ensure the registry exists
    if not hasattr(self, "_handlers"):
        self._handlers = {}

    # Validate the hook
    if hook is None:
        raise ValueError("Hook must not be None")

    # Get or create the list of handlers for this hook
    try:
        handlers = self._handlers.setdefault(hook, [])
    except Exception as exc:
        raise TypeError(f"Unhashable or unsupported hook type: {hook!r}") from exc

    def _decorate(func):
        if not callable(func):
            raise TypeError(f"Handler must be callable, got {type(func).__name__}")
        handlers.append(func)
        return func

    return _decorate

def get_versions():
    """Get version information or return default if unable to do so."""
    import os
    default_version = "0.0.0"
    try:
        # 1. Check environment variable
        env_ver = os.getenv("PACKAGE_VERSION")
        if env_ver:
            return env_ver.strip()

        # 2. Look for a VERSION file alongside this module
        try:
            curdir = os.path.dirname(__file__)
        except NameError:
            curdir = os.getcwd()
        ver_file = os.path.join(curdir, "VERSION")
        if os.path.isfile(ver_file):
            with open(ver_file, "r", encoding="utf-8") as f:
                return f.read().strip()

        # 3. Try importlib.metadata (Python 3.8+)
        try:
            from importlib.metadata import version as _get_version, PackageNotFoundError
            pkg = __package__ or ""
            if pkg:
                try:
                    return _get_version(pkg).strip()
                except (PackageNotFoundError, ValueError):
                    pass
        except Exception:
            # If importlib.metadata is unavailable, try importlib_metadata backport
            try:
                from importlib_metadata import version as _get_version
                pkg = __package__ or ""
                if pkg:
                    try:
                        return _get_version(pkg).strip()
                    except Exception:
                        pass
            except Exception:
                pass
    except Exception:
        pass
    return default_version

def plus_or_dot(pieces):
    """Return a '+' if we don't already have one, else return a '.'."""
    try:
        # Check if the element '+' is present
        if '+' in pieces:
            return '.'
    except Exception as exc:
        raise ValueError('pieces must be an iterable or string') from exc
    return '+'

def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """
    Validate storage root hierarchy.

    Returns:
        num_objects - number of objects checked
        good_objects - number of objects checked that were found to be valid
    """
    try:
        root = getattr(self, 'storage_root', None)
        if root is None:
            if show_warnings:
                print("storage_root attribute not set.")
            return 0, 0

        root = os.path.abspath(str(root))
        if not os.path.isdir(root):
            if show_warnings:
                print(f"storage_root '{root}' is not a directory.")
            return 0, 0

        num_objects = 0
        good_objects = 0

        for dirpath, dirnames, filenames in os.walk(root):
            for fname in filenames:
                num_objects += 1
                full_path = os.path.join(dirpath, fname)
                try:
                    if not os.path.isfile(full_path):
                        if show_warnings:
                            print(f"Skipping non-file entry: {full_path}")
                        continue
                    if validate_objects:
                        # Basic read check; more sophisticated validation can be added here
                        with open(full_path, 'rb') as f:
                            f.read(1)
                    if check_digests:
                        # Placeholder for digest checks – implement as needed
                        pass
                    good_objects += 1
                except Exception as e:
                    if show_warnings:
                        print(f"Error validating '{full_path}': {e}")

        return num_objects, good_objects

    except Exception as e:
        if show_warnings:
            print(f"Unexpected error during hierarchy validation: {e}")
        return 0, 0

def next_version(version):
    """Next version identifier following existing pattern.

    Must deal with both zero-prefixed and non-zero prefixed versions.
    """
    if not isinstance(version, str):
        raise TypeError("version must be a string")

    version = version.strip()
    if not version:
        raise ValueError("empty version string")

    parts = version.split('.')
    if not all(part.isdigit() for part in parts):
        raise ValueError("version must contain only numeric components separated by '.'")

    # Increment the last numeric component
    last = parts[-1]
    width = len(last)
    try:
        num = int(last) + 1
    except Exception as exc:
        raise ValueError("invalid numeric value in version") from exc

    new_last = str(num)
    # Preserve original padding if the new number is shorter
    if len(new_last) < width:
        new_last = new_last.zfill(width)

    return '.'.join(parts[:-1] + [new_last])

def validate_version_inventories(self, version_dirs):
    """Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).
    """
    import os
    import json

    # Determine the root directory that contains the inventories
    root_dir = getattr(self, "root_path", None)
    if root_dir is None:
        root_dir = getattr(self, "base_dir", None)
    if root_dir is None:
        raise RuntimeError("Cannot determine root directory for inventories.")

    # Load the root inventory
    root_inventory_path = os.path.join(root_dir, "inventory.json")
    if not os.path.isfile(root_inventory_path):
        raise FileNotFoundError(f"Root inventory not found at {root_inventory_path}.")
    try:
        with open(root_inventory_path, "r", encoding="utf-8") as f:
            root_inventory = json.load(f)
    except json.JSONDecodeError as e:
        raise ValueError(f"Root inventory JSON is malformed: {e}")

    differing_digests = {}

    # Iterate over each version directory in order
    for v_dir in version_dirs:
        inv_path = os.path.join(root_dir, v_dir, "inventory.json")
        if not os.path.isfile(inv_path):
            raise FileNotFoundError(f"Missing inventory in version directory '{v_dir}' (expected {inv_path}).")
        try:
            with open(inv_path, "r", encoding="utf-8") as f:
                inv = json.load(f)
        except json.JSONDecodeError as e:
            raise ValueError(f"Inventory JSON malformed in {inv_path}: {e}")

        # Verify that the version inventory is a mapping of paths to digests
        if not isinstance(inv, dict):
            raise TypeError(f"Inventory in {inv_path} must be a JSON object mapping file paths to digests.")

        # Compare each digest against the root inventory
        for rel_path, digest in inv.items():
            # The root must also contain the file; if not, it's an error
            if rel_path not in root_inventory:
                raise ValueError(f"File {rel_path!r} present in version '{v_dir}' but not found in root inventory.")
            root_digest = root_inventory[rel_path]
            if digest != root_digest:
                differing_digests[rel_path] = {"root_digest": root_digest, "version_digest": digest}

        # Ensure that the inventory does not contain unknown files (outside root)
        unexpected = set(inv.keys()) - set(root_inventory.keys())
        if unexpected:
            raise ValueError(f"Inventory in {v_dir} contains unknown files: {sorted(unexpected)}")

    # Record the differing digests for later validation
    self._differing_digests =

def find_path_type(path):
    """Return a string indicating the type of thing at the given path.

    Return values:
        'root' - looks like an OCFL Storage Root
        'object' - looks like an OCFL Object
        'file' - a file, might be an inventory
        other string explains error description

    Looks only at "0=*" Namaste files to determine the directory type.
    """
    import os
    try:
        p = str(path)
    except Exception as e:
        return f"invalid path: {e}"
    if not os.path.exists(p):
        return f"path does not exist: {p}"
    if os.path.isfile(p):
        return "file"
    if not os.path.isdir(p):
        return f"not a file or directory: {p}"
    try:
        entries = os.listdir(p)
    except Exception as e:
        return f"cannot list directory: {e}"
    # Count files that match the "0=*" pattern
    namaste_files = []
    for entry in entries:
        if entry.startswith("0="):
            full = os.path.join(p, entry)
            if os.path.isfile(full):
                namaste_files.append(entry)
    count = len(namaste_files)
    if count == 0:
        return "no Namaste files found"
    if count == 1:
        return "root"
    # When more than one Namaste file exists, likely an object
    return "object"

def amend_bzparams(self, params, bug_ids):
        """Amend the Bugzilla params
        Add the provided bug_ids to the parameters dictionary used to query
        Bugzilla. The method ensures that the `params` argument is a dictionary
        and that `bug_ids` can be interpreted as an iterable of integers or
        strings. It returns a new dictionary that contains all original
        parameters plus the key ``'ids'`` set to the list of bug IDs.
        Invalid types raise a ``TypeError``.
        """
        # Validate params is a dict
        if not isinstance(params, dict):
            raise TypeError(f"'params' must be a dictionary, got {type(params).__name__}")

        # Convert bug_ids to a list
        if isinstance(bug_ids, (list, tuple, set)):
            bug_id_list = list(bug_ids)
        elif isinstance(bug_ids, (int, str)):
            bug_id_list = [bug_ids]
        else:
            raise TypeError(f"'bug_ids' must be an int, str, list, tuple, or set, got {type(bug_ids).__name__}")

        # Ensure bug IDs are hashable and reasonable
        cleaned_ids = []
        for bid in bug_id_list:
            try:
                # Accept ints or strings that represent ints
                if isinstance(bid, int):
                    cleaned_ids.append(bid)
                elif isinstance(bid, str) and bid.isdigit():
                    cleaned_ids.append(int(bid))
                elif isinstance(bid, str):
                    cleaned_ids.append(bid)
                else:
                    raise ValueError
            except Exception:
                raise ValueError(f"Invalid bug ID value: {bid!r}") from None

        # Create a new params dict to avoid mutating the caller's dict
        new_params = params.copy()
        new_params['ids'] = cleaned_ids
        return new_params

def parser_flags(parser):
    """
    Given an argparse.ArgumentParser instance, return its argument flags in a
    space-separated string.
    """
    # Basic validation of the parser object
    if parser is None or not hasattr(parser, 'actions'):
        raise TypeError("Expected an argparse.ArgumentParser instance")

    flags = []
    for action in parser.actions:
        try:
            # Optional arguments expose their option strings
            if action.option_strings:
                flags.extend(action.option_strings)
            else:
                # Positional arguments generally lack option strings;
                # use the destination name as the flag if present
                dest = getattr(action, 'dest', None)
                if dest:
                    flags.append(dest)
        except Exception:
            # Silently ignore actions that do not follow the expected interface
            continue

    return ' '.join(flags)

def parse_arguments(*unparsed_arguments):
    '''
    Given command-line arguments with which this script was invoked, parse the arguments and return
    them as a dict mapping from subparser name (or "global") to an argparse.Namespace instance.
    '''
    # The function assumes that `argparse` is available in the module where this function is called.
    # It creates a very general parser that does not define any specific arguments, so that
    # any supplied arguments are treated as "unknown" and then grouped by subparser name.
    parser = argparse.ArgumentParser()
    try:
        parsed, remaining = parser.parse_known_args(unparsed_arguments)
    except Exception as exc:
        # If parsing fails for global options, capture the error in a Namespace.
        return {'global': argparse.Namespace(error=str(exc))}

    result = {'global': parsed}

    # Group remaining tokens by subparser name: treat any token that does not start with '-' as a name,
    # and the tokens that follow it as its arguments until the next name token.
    subparsers = {}
    current = None
    for token in remaining:
        if not token.startswith('-'):
            current = token
            subparsers[current] = []
        else:
            if current is None:
                # Unknown option before any subparser name; attach it to global Namespace under 'unknown'
                unknown = result.setdefault('global', argparse.Namespace()).__dict__.setdefault('unknown', [])
                unknown.append(token)
            else:
                subparsers[current].append(token)

def deep_merge_nodes(nodes):
    """
    Merge a list of (ScalarNode, Node) tuples by deep merging MappingNodes
    with duplicate keys. Non-mapping values are overwritten by the last
    occurrence.
    """
    # Helper to check if a node is a mapping node
    def is_mapping(node):
        try:
            return node.tag.startswith('tag:yaml.org,2002:map')
        except Exception:
            return False

    # Recursively merge two lists of (ScalarNode, Node) tuples
    def merge_lists(list1, list2):
        merged = list1[:]  # start with the first list
        for key_node, val_node in list2:
            key = getattr(key_node, 'value', None)
            # Find if key already exists in merged list
            found = False
            for idx, (k_node, v_node) in enumerate(merged):
                if getattr(k_node, 'value', None) == key:
                    found = True
                    if is_mapping(v_node) and is_mapping(val_node):
                        merged[idx] = (k_node, merge_mapping_nodes(v_node, val_node))
                    else:
                        merged[idx] = (k_node, val_node)
                    break
            if not found:
                merged.append((key_node, val_node))
        return merged

    # Merge two mapping nodes
    def merge_mapping_nodes(existing, new):
        merged_value = merge_lists(existing.value, new.value)
        # Create a new MappingNode with the same tag; reuse the node type
        MappingNodeType = type(existing)
        return MappingNodeType(existing.tag, merged_value)

    # Main merge process
    try:
        # Map key string to (key_node, value_node)
        merged_dict = {}
        for key_node, val_node in nodes:
            key = getattr(key_node, 'value', None)
            if key in merged_dict:
                existing_val = merged_dict[key][1]
                if is_mapping(existing_val) and is_mapping(val_node):
                    merged_dict[key] = (merged_dict[key][0], merge_mapping_nodes(existing_val, val_node))
                else:
                    merged_dict[key] = (merged_dict[key][0], val_node)
            else:
                merged_dict[key] = (key_node, val_node)
        # Build result list preserving order of first occurrences
        result = [(k, v) for _, (k, v) in merged_dict.items()]
        return result
    except Exception as e:
        # If any unexpected error occurs, return an empty list
        return []

def parser_flags(parser):
    '''
    Given an argparse.ArgumentParser instance, return its argument flags in a space-separated
    string.
    '''
    # Validate input
    if parser is None:
        raise TypeError("parser cannot be None")
    try:
        actions = getattr(parser, "_actions", [])
        if not isinstance(actions, (list, tuple)):
            raise TypeError
    except Exception as exc:
        raise TypeError("Invalid parser object") from exc

    flags = []
    for action in actions:
        # Most actions have 'option_strings' attribute containing command line flags
        try:
            opt = getattr(action, "option_strings", None)
        except Exception:
            continue
        if opt:
            for flag in opt:
                if isinstance(flag, str) and flag:
                    flags.append(flag)

    return " ".join(flags) if flags else ""

def paging(response, max_results):
    """Returns WAPI response page by page

    Args:
        response (list): WAPI response.
        max_results (int): Maximum number of objects to be returned in one page.
    Returns:
        Generator object with WAPI response split page by page.
    """
    # Validate input types
    if response is None:
        raise ValueError("Response cannot be None.")
    if not isinstance(response, list):
        raise ValueError(f"Response must be a list, got {type(response).__name__}.")
    if not isinstance(max_results, int):
        raise ValueError(f"max_results must be an integer, got {type(max_results).__name__}.")
    if max_results <= 0:
        raise ValueError("max_results must be a positive integer.")

    # Generator that yields slices of the list
    def _generator(data, chunk):
        for start in range(0, len(data), chunk):
            yield data[start:start + chunk]

    return _generator(response, max_results)

def _replace_url_args(url, url_args):
    """Replace any custom string URL items with values in args

    Args:
        url (str): URL that may contain placeholders like ``{key}`` or ``:key``.
        url_args (dict): Mapping from placeholder names to replacement values.

    Returns:
        str: URL with placeholders replaced by the corresponding values.

    Raises:
        TypeError: If ``url`` is not a string or ``url_args`` is not a dict.
    """
    if not isinstance(url, str):
        raise TypeError(f"Expected url to be a str, got {type(url).__name__}")
    if not isinstance(url_args, dict):
        raise TypeError(f"Expected url_args to be a dict, got {type(url_args).__name__}")

    import re

    # Matches {key} or :key
    placeholder_pattern = re.compile(r'\{(\w+)\}|\:(\w+)')

    def _repl(match):
        key = match.group(1) or match.group(2)
        if key in url_args:
            val = url_args[key]
            if val is None:
                val = ''
            return str(val)
        # leave placeholder unchanged if key not found
        return match.group(0)

    try:
        return placeholder_pattern.sub(_repl, url)
    except Exception as exc:  # pragma: no cover
        # In case of any unexpected errors, return the original URL
        return url

def is_none_string(val: any) -> bool:
    """Check if a string represents a None value."""
    # If the value itself is None, we consider it a None representation
    if val is None:
        return True

    # If the value is a string, inspect its content
    if isinstance(val, str):
        # Remove surrounding whitespace and convert to lowercase for a case-insensitive comparison
        clean = val.strip().lower()
        # Common textual representations of None
        return clean in ('', 'none', 'null')

    # Any non-string/non-None value is not considered a string representation of None
    return False

def parser_flags(parser):
    '''
    Given an argparse.ArgumentParser instance, return its argument flags in a space-separated
    string.
    '''
    if parser is None:
