def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    # Validate inputs
    if not isinstance(number, int):
        raise TypeError("number must be an integer")
    if not isinstance(alphabet, list) or len(alphabet) == 0:
        raise ValueError("alphabet must be a non-empty list")
    for idx, char in enumerate(alphabet):
        if not isinstance(char, str):
            raise TypeError(f"alphabet element at index {idx} is not a string")
        if len(char) != 1:
            raise ValueError(f"alphabet element at index {idx} must be a single character")
    if len(set(alphabet)) != len(alphabet):
        raise ValueError("alphabet elements must be unique")
    if padding is not None:
        if not isinstance(padding, int):
            raise TypeError("padding must be an integer or None")
        if padding < 0:
            raise ValueError("padding must be non-negative")

    base = len(alphabet)
    neg = number < 0
    n = -number if neg else number

    # Special case for zero
    if n == 0:
        digits = [alphabet[0]]
    else:
        digits = []
        while n > 0:
            digits.append(alphabet[n % base])
            n //= base
        digits.reverse()

    # Apply padding if necessary
    if padding is not None and padding > len(digits):
        pad_count = padding - len(digits)
        digits = [alphabet[0]] * pad_count + digits

    result = ''.join(digits)
    if neg:
        result = '-' + result
    return result

def _replace_register(flow_params, register_number, register_value):
    """Replace value from flows to given register number

    'register_value' key in dictionary will be replaced by register number
    given by 'register_number'

    :param flow_params: Dictionary containing defined flows
    :param register_number: The number of register where value will be stored
    :param register_value: Key to be replaced by register number

    :return: The modified flow_params with register values replaced.
    """
    def _recursive_replace(item):
        if isinstance(item, dict):
            for key, val in list(item.items()):
                if key == register_value:
                    item[key] = register_number
                # Recurse into nested structures
                if isinstance(val, (dict, list)):
                    _recursive_replace(val)
        elif isinstance(item, list):
            for elem in item:
                _recursive_replace(elem)

    if not isinstance(flow_params, (dict, list)):
        raise TypeError("flow_params must be a dict or list")
    try:
        _recursive_replace(flow_params)
    except Exception as e:
        raise RuntimeError(f"Error replacing register {register_number} for key '{register_value}': {e}") from e
    return flow_params

def replace_dots(value, arg):
    """Replaces all values of '.' to arg from the given string"""
    try:
        if not isinstance(value, str):
            raise TypeError("value must be a string")
        if not isinstance(arg, str):
            raise TypeError("arg must be a string")
        return value.replace(".", arg)
    except Exception as exc:
        # Re-raise with additional context or return original value
        raise ValueError(f"Error in replace_dots: {exc}") from exc

def subclasses(cls):
    """Return all subclasses of a class, recursively"""
    if not isinstance(cls, type):
        raise TypeError('subclasses() requires a class')
    subs = set()
    for sub in cls.__subclasses__():
        subs.add(sub)
        subs.update(subclasses(sub))
    return subs

def string_to_int(string: str, alphabet: List[str]) -> int:
    """
    Convert a string to a number, using the given alphabet.

    The input is assumed to have the most significant digit first.
    """
    # Basic validation of base and alphabet uniqueness
    base = len(alphabet)
    if base <= 1:
        raise ValueError("Alphabet must contain at least two distinct symbols to form a base.")
    if len(set(alphabet)) != base:
        raise ValueError("Alphabet symbols must be unique.")

    # Create a mapping from symbol to its numeric value
    symbol_to_value = {symbol: idx for idx, symbol in enumerate(alphabet)}

    if not string:
        raise ValueError("Input string cannot be empty.")

    value = 0
    for ch in string:
        try:
            digit = symbol_to_value[ch]
        except KeyError:
            raise ValueError(f"Character '{ch}' not found in the provided alphabet.")
        value = value * base + digit

    return value

def unquote(name):
    """Remove quote from the given name."""
    # Validate input type
    if not isinstance(name, str):
        raise TypeError("name must be a string")
    # Return empty string as-is
    if not name:
        return name
    # Check if the first and last characters are matching quotes
    if len(name) >= 2 and name[0] == name[-1] and name[0] in ("'", '"'):
        return name[1:-1]
    # If not surrounded by matching quotes, return the original string
    return name

def split(s, platform='this'):
    """Multi-platform variant of shlex.split() for command-line splitting.
    For use with subprocess, for argv injection etc. Using fast REGEX.

    platform: 'this' = auto from current platform;
              1 = POSIX;
              0 = Windows/CMD
              (other values reserved)
    """
    # Validate input
    if not isinstance(s, str):
        raise TypeError(f"expected a string, got {type(s).__name__}")

    # Resolve platform flag
    try:
        if platform == 'this':
            import os
            # os.name: 'nt' on Windows, 'posix' on POSIX
            posix_mode = os.name != 'nt'
        elif platform in (1, 'posix', 'POSIX', 'POSIX'):
            posix_mode = True
        elif platform in (0, 'windows', 'cmd', 'CMD'):
            posix_mode = False
        else:
            raise ValueError(f"invalid platform value: {platform!r}")
    except Exception as exc:
        raise ValueError(f"Error determining platform: {exc}") from exc

    # Use shlex for robust parsing according to platform
    try:
        import shlex
        return shlex.split(s, posix=posix_mode)
    except ValueError as exc:
        # Re-raise with clearer context
        raise ValueError(f"failed to parse command: {exc}") from exc
    except Exception as exc:
        # Unexpected errors
        raise RuntimeError(f"unexpected error during split: {exc}") from exc

def addignored(ignored):
    '''Use the git command to obtain the file names, turn it into a list, sort the list for only ignored files, return those files as a single string with each filename separated by a comma.'''
    try:
        # Retrieve ignored files from the current git repository
        output = subprocess.check_output(
            ['git', 'ls-files', '-i', '--exclude-standard'],
            universal_newlines=True,
            stderr=subprocess.DEVNULL
        )
        # Split into lines, filter out any empty entries, and sort
        files = sorted([f for f in output.splitlines() if f.strip()])
        # Return a comma‑separated string of file names
        return ','.join(files)
    except (subprocess.CalledProcessError, FileNotFoundError):
        # If git is not available or this is not a git repo, return an empty string
        return ''

def match(filename):
    """
    Check if the filename is a type that this module supports

    Args:
        filename: Filename to match
    Returns:
        False if not a match, True if supported
    """
    try:
        if not isinstance(filename, str) or not filename:
            return False
        _, ext = os.path.splitext(filename)
        supported = {'.txt', '.csv', '.json', '.xml'}
        return ext.lower() in supported
    except Exception:
        return False

def write_configuration(config_filename, rendered_config, mode=0o600, overwrite=False):
    '''
    Given a target config filename and rendered config YAML, write it out to file. Create any
    containing directories as needed. But if the file already exists and overwrite is False,
    abort before writing anything.
    '''
    # Validate inputs
    if config_filename is None:
        raise ValueError('config_filename must not be None')
    if not isinstance(config_filename, (str, os.PathLike)):
        raise TypeError('config_filename must be a string or path-like object')
    if not isinstance(rendered_config, str):
        raise TypeError('rendered_config must be a string containing YAML')
    if not isinstance(mode, int):
        raise TypeError('mode must be an integer file permission value')
    if not isinstance(overwrite, bool):
        raise TypeError('overwrite must be a boolean')

    target_path = os.fspath(config_filename)
    if os.path.exists(target_path) and not overwrite:
        raise FileExistsError(f'File {target_path} already exists and overwrite is False')

    # Ensure parent directories exist
    parent_dir = os.path.dirname(target_path)
    if parent_dir:
        try:
            os.makedirs(parent_dir, exist_ok=True)
        except Exception as exc:
            raise OSError(f'Could not create directories {parent_dir!r}: {exc}') from exc

    # Write the rendered configuration
    try:
        with open(target_path, 'w', encoding='utf-8') as fp:
            fp.write(rendered_config)
    except Exception as exc:
        raise IOError(f'Failed to write configuration to {target_path!r}: {exc}') from exc

    # Set file permissions
    try:
        os.chmod(target_path, mode)
    except Exception as exc:
        raise OSError(f'Failed to set permissions {oct(mode)} on {target_path!r}: {exc}') from exc
    return

def _resolve_string(matcher):
    '''
    Get the value from environment given a matcher containing a name and an optional default value.
    If the variable is not defined in environment and no default value is provided, an Error is raised.
    '''
    # Determine name and default from matcher
    if isinstance(matcher, dict):
        if 'name' not in matcher:
            raise ValueError('Matcher dict must contain a "name" key')
        name = matcher['name']
        default = matcher.get('default', None)
    elif isinstance(matcher, (list, tuple)):
        if len(matcher) == 0:
            raise ValueError('Matcher tuple/list must contain at least the variable name')
        name = matcher[0]
        default = matcher[1] if len(matcher) > 1 else None
    else:
        raise TypeError('Matcher must be a dict, list, or tuple')

    # Fetch the variable from the environment
    try:
        value = os.environ.get(name)
    except Exception as exc:
        raise RuntimeError(f'Error accessing environment variable "{name}": {exc}')

    # If not found and default is not provided, raise an error
    if value is None:
        if default is None:
            raise ValueError(f'Environment variable "{name}" is not defined and no default value provided')
        value = default

    return str(value)

def remove_ending_os_sep(input_list):
    if not isinstance(input_list, list):
        raise TypeError("input_list must be a list")
    result = []
    for item in input_list:
        if not isinstance(item, str):
            raise TypeError("All items in input_list must be strings")
        if len(item) > 1 and item[-1] == os.sep:
            result.append(item[:-1])
        else:
            result.append(item)
    return result

def get_pattern(pattern, strip=True):
    """
    This method converts the given string to regex pattern
    """
    # Validate input type
    if pattern is None:
        raise TypeError("pattern must not be None")
    if not isinstance(pattern, str):
        raise TypeError(f"pattern must be a string, got {type(pattern).__name__}")
    try:
        # Optionally strip whitespace
        if strip:
            pattern = pattern.strip()
        # Escape regex special characters to match the literal string
        escaped = re.escape(pattern)
        return escaped
    except Exception as exc:
        raise ValueError(f"Error converting pattern to regex: {exc}")

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    # Validate input types
    if commands is None:
        raise ValueError("`commands` must not be None")
    if not isinstance(commands, (str, list)):
        raise TypeError("`commands` must be a str or list")
    if args is None:
        args = []
    if not isinstance(args, list):
        raise TypeError("`args` must be a list of arguments")
    # Build the command list
    if isinstance(commands, str):
        cmd = [commands]
    else:
        cmd = commands[:]
    cmd.extend(args)
    # Prepare subprocess parameters
    subprocess_kwargs = {
        "cwd": cwd,
        "env": env,
        "text": True,
        "capture_output": True,
        "check": True,
    }
    if hide_stderr:
        subprocess_kwargs["stderr"] = subprocess.DEVNULL
    try:
        result = subprocess.run(cmd, **subprocess_kwargs)
        if verbose:
            # Print the command that was run
            print(f"Command: {' '.join(cmd)}")
            # Show stdout
            if result.stdout:
                print("Stdout:")
                print(result.stdout)
            # Show stderr if not hidden
            if not hide_stderr and result.stderr:
                print("Stderr:")
                print(result.stderr)
        return result
    except subprocess.CalledProcessError as e:
        # If verbose, print error details
        if verbose:
            print(f"Command '{' '.join(e.cmd)}' failed with return code {e.returncode}")
            if e.stdout:
                print("Stdout:")
                print(e.stdout)
            if not hide_stderr and e.stderr:
                print("Stderr:")
                print(e.stderr)
        raise RuntimeError(f"Command '{' '.join(e.cmd)}' failed") from e
    except Exception as exc:
        raise RuntimeError(f"Error running command '{' '.join(cmd)}': {exc}") from exc

def is_ipv4(target):
    """Test if IPv4 address or not."""
    try:
        addr = ipaddress.ip_address(str(target))
    except (ValueError, TypeError):
        return False
    return isinstance(addr, ipaddress.IPv4Address)

def make_array(shape, dtype=np.dtype("float32")):
    """
    Function to create an array with shape and dtype.

    Parameters
    ----------
    shape : tuple
        shape of the array to create
    dtype : `numpy.dtype`
        data-type of the array to create
    """
    # Validate the shape
    if not isinstance(shape, (tuple, list)):
        raise TypeError("shape must be a tuple or list of non‑negative integers")

    for dim in shape:
        if not isinstance(dim, int):
            raise TypeError(f"shape dimension {dim!r} is not an integer")
        if dim < 0:
            raise ValueError(f"shape dimension {dim!r} must be non‑negative")

    # Validate the dtype
    try:
        dtype_obj = np.dtype(dtype)
    except Exception as exc:
        raise TypeError(f"invalid dtype {dtype!r}") from exc

    # Attempt to create the array
    try:
        arr = np.empty(shape, dtype=dtype_obj)
    except Exception as exc:
        raise ValueError(f"could not create array with shape {shape!r} "
                         f"and dtype {dtype_obj}") from exc

    return arr

def gaussian(x):
    """
    Gaussian centered around 0.2 with a sigma of 0.1.
    Returns the value of the Gaussian probability density function at x.
    """
    try:
        x = np.asarray(x, dtype=float)
    except Exception:
        raise ValueError("Input must be a numeric or array-like value.") from None

    mean = 0.2
    sigma = 0.1

    if sigma <= 0:
        raise ValueError("Sigma must be positive.")

    coef = 1.0 / (sigma * np.sqrt(2 * np.pi))
    return coef * np.exp(-((x - mean) ** 2) / (2 * sigma ** 2))

def _get_seq_with_type(seq, bufsize=None):
    """
    Return a (sequence, type) pair.
    Sequence is derived from *seq*
    (or is *seq*, if that is of a sequence type).
    """
    # Determine if the given object is already a sequence type.
    # Here we consider list, tuple, str, bytes, range and set as sequence-like objects.
    # Note: set is not an ordered sequence, but it is iterable and often treated as a collection.
    if seq is None:
        raise TypeError("seq must not be None")

    # If the input is already a recognized sequence type, use it as is
    if isinstance(seq, (list, tuple, str, bytes, range, set)):
        return seq, type(seq)

    # If the input is not a sequence, attempt to derive a sequence from it.
    # We try to iterate over it and construct a list.
    try:
        derived = list(seq)
    except TypeError:
        # Non-iterable: treat the element itself as a one-element sequence
        derived = [seq]

    # If bufsize is provided, optionally chunk the derived sequence into sublists
    # of size *bufsize*. This is optional and only applied when bufsize is a positive int.
    if bufsize is not None:
        try:
            sz = int(bufsize)
            if sz > 0:
                derived = [derived[i:i + sz] for i in range(0, len(derived), sz)]
        except Exception:
            # If bufsize cannot be coerced to a positive int, ignore it.
            pass

    return derived, type(derived)

def scale(self, other=None, recompute=False):
        """
        Compute or set scale (integral of the histogram).

        If *other* is ``None``, return scale of this histogram.
        If its scale was not computed before, it is computed and stored for
        subsequent use (unless explicitly asked to *recompute*). Note that
        after changing (filling) the histogram one must explicitly recompute
        the scale if it was computed before.

        If a float *other* is provided, rescale self to *other*.

        Histograms with scale equal to zero can't be rescaled;
        :exc:`.LenaValueError` is raised if one tries to do that.
        """
        # Helper to compute the scale from current bin contents
        def _compute_current_scale():
            bins = getattr(self, "bins", getattr(self, "_bins", []))
            try:
                return float(sum(bins))
            except Exception:
                return 0.0

        # If no target scale is given, return (and possibly compute) the current scale
        if other is None:
            # recompute if requested or if never computed before
            if recompute or not getattr(self, "_scale_computed", False):
                self._scale = _compute_current_scale()
                self._scale_computed = True
            # ensure attribute exists before returning
            return getattr(self, "_scale", 0.0)

        # Otherwise, *other* is intended as the target scale
        if not isinstance(other, (int, float)):
            raise TypeError("Scale must be a numeric type")

        current_scale = self.scale(recompute=True)  # Get latest scale
        if current_scale == 0:
            raise LenaValueError("Cannot rescale histogram with zero scale")

        # Compute scaling factor and apply to each bin
        factor = float(other) / current_scale
        bins = getattr(self, "bins", getattr(self, "_bins", []))
        if isinstance(bins, (list, tuple)):
            for idx in range(len(bins)):
                bins[idx] *= factor
        else:
            # Attempt to iterate over bins if it's an iterable of items
            try:
                for item in bins:
                    item[0] *= factor  # assuming (value, bin) structure
            except Exception:
                # If bins object does not support scaling, raise an error
                raise TypeError("Histogram bins cannot be rescaled")

        # Store the new scale
        self._scale = float(other)
        self._scale_computed = True
        return self._scale

