def pop(self, key, default=__marker):
    """
    D.pop(k[,d]) -> v, remove specified key and return the corresponding value.
    If key is not found, d is returned if given, otherwise KeyError is raised.
    """
    try:
        value = self[key]
    except KeyError:
        if default is __marker:
            raise
        return default
    try:
        del self[key]
    except KeyError:
        # Handle race condition: key disappeared between lookup and delete.
        if default is __marker:
            raise
        return default
    return value

def popitem(self):
    """Remove and return the `(key, value)` pair least frequently used."""
    # Ensure the structure has the expected attributes
    try:
        store = getattr(self, "_store")
        freq = getattr(self, "_freq")
    except AttributeError:
        raise AttributeError(
            "The container lacks the required '_store' or '_freq' attributes."
        )

    if not store:
        raise KeyError("popitem from an empty container")

    # Identify the key with the minimum frequency
    # Ties are resolved by the natural ordering of keys
    min_key = min(freq, key=freq.get)

    # Retrieve the value and remove both key and frequency entries
    value = store.pop(min_key, None)
    freq.pop(min_key, None)

    return (min_key, value)

def popitem(self):
    """Remove and return the `(key, value)` pair most recently used."""
    try:
        # Preferred: use the ordered popitem if available
        return super().popitem(last=True)
    except TypeError:
        # Fallback for older OrderedDict implementations that don't accept 'last'
        try:
            return super().popitem()
        except KeyError:
            # Mimic the exception raised by OrderedDict/popitem when empty
            raise IndexError("popitem(): dictionary is empty") from None
    except KeyError:
        # Dictionary is empty
        raise IndexError("popitem(): dictionary is empty") from None

def popitem(self):
    """Remove and return a random `(key, value)` pair."""
    # Verify that self is a mapping with a length
    try:
        if len(self) == 0:
            raise KeyError('popitem(): dictionary is empty')
    except Exception:
        raise TypeError('popitem() argument must be a mapping')
    # Gather keys; this also checks that keys() is available
    try:
        keys = list(self.keys())
    except Exception:
        raise TypeError('object does not support keys()')
    if not keys:
        # Should not happen if len > 0, but guard anyway
        raise KeyError('popitem(): dictionary is empty')
    # Choose a pseudo-random index using a hash of the object's id
    index = hash(id(self)) % len(keys)
    key = keys[index]
    # Retrieve the value and remove the mapping
    try:
        value = self[key]
    except KeyError:
        raise KeyError(f'key {key} not found during popitem')
    try:
        del self[key]
    except Exception as e:
        raise KeyError(f'failed to delete key {key}') from e
    return (key, value)

def _create_in_regex(self) -> Pattern:
    """
    Create the in-style parameter regular expression.

    Returns the in-style parameter regular expression (:class:`re.Pattern`).
    """
    try:
        # Matches the word IN followed by a parenthesized list,
        # optionally containing `NOT` before IN and allowing
        # whitespace around the parentheses and comma-separated values.
        pattern = r'\b(?:NOT\s+)?IN\s*\(\s*(?P<items>[^)]*?)\s*\)'
        return re.compile(pattern, re.IGNORECASE)
    except re.error:
        # Fallback to a very generic pattern if compilation fails
        return re.compile(r'in\s*\([^)]*\)', re.IGNORECASE)

def identify_request(request: RequestType):
    """Try to identify whether this is a Diaspora request.

    Try first public message. Then private message. The check if this is a legacy payload.
    """
    def _contains_diaspora(data):
        """
        Recursively check if data (dict or string) contains the keyword 'diaspora'.
        """
        if isinstance(data, dict):
            for key, value in data.items():
                if isinstance(key, str) and 'diaspora' in key.lower():
                    return True
                if isinstance(value, str) and 'diaspora' in value.lower():
                    return True
                # recursion for nested dicts or lists
                if isinstance(value, dict) or isinstance(value, list):
                    if _contains_diaspora(value):
                        return True
            return False
        if isinstance(data, list):
            for item in data:
                if _contains_diaspora(item):
                    return True
            return False
        if isinstance(data, str):
            return 'diaspora' in data.lower()
        return False

    if request is None:
        return False

    try:
        # Fetch public, private, and legacy parts from either dict or object attributes
        if isinstance(request, dict):
            public_msg = request.get('public_msg')
            private_msg = request.get('private_msg')
            legacy = request.get('legacy')
        else:
            public_msg = getattr(request, 'public_msg', None)
            private_msg = getattr(request, 'private_msg', None)
            legacy = getattr(request, 'legacy', None)

        # Check public message first
        if public_msg and _contains_diaspora(public_msg):
            return True
        # If not found, check private message
        if private_msg and _contains_diaspora(private_msg):
            return True
        # Finally, check legacy payload
        if legacy and _contains_diaspora(legacy):
            return True

        return False
    except Exception:
        # In case of any unexpected error (e.g., wrong type), return False
        return False

def identify_request(request: RequestType) -> bool:
    """
    Try to identify whether this is a Matrix request.

    Matrix API requests are typically addressed with a URL path that starts with
    `/_matrix`.  In addition to the path check we also glance at the headers for
    any Matrix‑specific tokens.  The function is defensive: it will return
    ``False`` for any invalid input or any exception that might be raised while
    examining the request object.
    """
    try:
        # Quick guard against a completely invalid request
        if request is None:
            return False

        # Extract the path – try the common attributes in order.
        path = None
        if hasattr(request, "path"):
            path = request.path
        elif hasattr(request, "url"):
            # Naive extraction of the path from a URL string
            url = request.url
            # Remove scheme if present
            if "://" in url:
                url = url.split("://", 1)[1]
            # Remove query string and fragment
            url = url.split("?", 1)[0].split("#", 1)[0]
            # Split on the first slash after the host
            if "/" in url:
                path = url.split("/", 1)[1]
                path = "/" + path
            else:
                path = "/"
        else:
            # No recognizable location information – bail out
            return False

        # Ensure the path is a string and starts with the Matrix prefix
        if isinstance(path, str) and path.startswith("/_matrix"):
            return True

        # Fall back to header inspection – look for any obvious Matrix hint
        headers = getattr(request, "headers", {})
        if isinstance(headers, dict):
            for key, value in headers.items():
                if isinstance(key, str) and "matrix" in key.lower():
                    return True
                if isinstance(value, str) and "matrix" in value.lower():
                    return True

        return False
    except Exception:
        # In case of any error during introspection, conservatively return False
        return False

def format_dt(dt):
    """
    Format a datetime in the way that D* nodes expect.
    The function converts the input datetime to UTC (if timezone-aware)
    or assumes UTC (if naive). The resulting string is in ISO-8601
    format with UTC designator 'Z', e.g. '2023-07-25T14:30:00Z'.
    Strings can also be accepted if they are ISO-8601 compliant.
    """
    import datetime
    if dt is None:
        return ''
    # If we receive a datetime instance
    if isinstance(dt, datetime.datetime):
        # Normalize to UTC
        if dt.tzinfo is not None:
            utc_dt = dt.astimezone(datetime.timezone.utc)
        else:
            utc_dt = dt
        return utc_dt.strftime('%Y-%m-%dT%H:%M:%SZ')
    # If we receive a string, try to parse it
    if isinstance(dt, str):
        try:
            # Handle 'Z' as UTC
            iso_str = dt.replace('Z', '+00:00')
            parsed = datetime.datetime.fromisoformat(iso_str)
            if parsed.tzinfo is not None:
                parsed = parsed.astimezone(datetime.timezone.utc)
            return parsed.strftime('%Y-%m-%dT%H:%M:%SZ')
        except Exception as exc:
            raise TypeError(f"Unable to parse datetime string '{dt}': {exc}") from exc
    raise TypeError(f"Unsupported type for dt: {type(dt)}")

def test_tag(tag: str) -> bool:
    """Test a word whether it could be accepted as a tag."""
    try:
        if not isinstance(tag, str) or not tag:
            return False
        # Optional length restriction (e.g., maximum 30 characters)
        if len(tag) > 30:
            return False
        # Regex: must start with a letter, followed by letters, digits, hyphens or underscores
        import re
        pattern = r'^[A-Za-z][A-Za-z0-9_-]*$'
        return re.match(pattern, tag) is not None
    except Exception:
        return False

def get_nodeinfo_well_known_document(url, document_path=None):
    """Generate a NodeInfo .well-known document.

    See spec: http://nodeinfo.diaspora.software

    :arg url: The full base url with protocol, ie https://example.com
    :arg document_path: Custom NodeInfo document path if supplied (optional)
    :returns: dict
    """
    # Basic validation for url
    if not isinstance(url, str) or not url:
        raise ValueError("`url` must be a non-empty string")
    if not (url.startswith("http://") or url.startswith("https://")):
        raise ValueError("`url` must start with http:// or https://")

    # Default document path
    if document_path is None:
        document_path = "/nodeinfo/2.0"

    # Validate document_path
    if not isinstance(document_path, str):
        raise ValueError("`document_path` must be a string")
    if not document_path.startswith("/"):
        raise ValueError("`document_path` must start with a '/'")

    # Construct href
    base = url.rstrip("/")
    href = f"{base}{document_path}"

    # Build the well-known document as per NodeInfo spec
    try:
        nodeinfo = {
            "links": [
                {
                    "rel": "http://nodeinfo.diaspora.software/ns/schema/2.0",
                    "href": href,
                    "type": "application/json",
                }
            ]
        }
    except Exception as exc:
        raise RuntimeError(f"Failed to construct NodeInfo document: {exc}") from exc

    return nodeinfo

def try_retrieve_webfinger_document(handle: str) -> Optional[str]:
    """
    Try to retrieve an RFC7033 webfinger document. Does not raise if it fails.
    """
    try:
        if '@' not in handle:
            return None
        # Split the handle into user and host parts
        acct_user, host = handle.split('@', 1)
        resource = f"acct:{handle}"
        # Attempt with HTTPS first, then fallback to HTTP
        for scheme in ("https", "http"):
            url = f"{scheme}://{host}/.well-known/webfinger?resource={resource}"
            try:
                # Import inside the function to avoid global import statements
                import urllib.request
                import urllib.error

                req = urllib.request.Request(
                    url, headers={"Accept": "application/json"}
                )
                with urllib.request.urlopen(req, timeout=5) as resp:
                    if resp.status == 200:
                        return resp.read().decode("utf-8")
            except (urllib.error.URLError, urllib.error.HTTPError, Exception):
                # If the request fails, try the next scheme
                continue
        return None
    except Exception:
        # On any unexpected error, return None without raising
        return None

def retrieve_diaspora_host_meta(host):
    """
    Retrieve a remote Diaspora host-meta document.

    :arg host: Host to retrieve from
    :returns: ``XRD`` instance
    """
    if not host or not isinstance(host, str):
        raise ValueError("host must be a non-empty string")

    # Normalise host by stripping any scheme
    host = host.strip()
    if host.lower().startswith("http://"):
        host = host[7:]
    elif host.lower().startswith("https://"):
        host = host[8:]

    # Construct the well‑known host‑meta URL
    url = f"https://{host}/.well-known/host-meta"

    # Use urllib to fetch the document
    try:
        import urllib.request
        import urllib.error
    except ImportError:
        raise RuntimeError("urllib is required to fetch host-meta")

    def _fetch(url):
        req = urllib.request.Request(
            url,
            headers={"User-Agent": "DiasporaMetaRetriever/1.0"},
            method="GET",
        )
        with urllib.request.urlopen(req, timeout=10) as response:
            if response.status != 200:
                raise ValueError(
                    f"HTTP error {response.status} while retrieving host-meta from {url}"
                )
            return response.read()

    try:
        data = _fetch(url)
    except urllib.error.URLError:
        # Fall back to http if https fails
        url_alt = f"http://{host}/.well-known/host-meta"
        try:
            data = _fetch(url_alt)
        except Exception as exc:
            raise ValueError(f"Could not retrieve host-meta from {host}: {exc}")

    # Parse the XML into an XRD instance
    try:
        # Assume XRD is imported in the caller's context
        xrd_obj = XRD(data)
        return xrd_obj
    except Exception as exc:
        raise ValueError(f"Failed to parse host-meta as XRD: {exc}")

def send_document(url, data, timeout=10, method="post", *args, **kwargs):
    """Helper method to send a document via POST.

    Additional ``*args`` and ``**kwargs`` will be passed on to ``requests.post``.

    :arg url: Full url to send to, including protocol
    :arg data: Dictionary (will be form-encoded), bytes, or file-like object to send in the body
    :arg timeout: Seconds to wait for response (defaults to 10)
    :arg method: Method to use, defaults to post
    :returns: Tuple of status code (int or None) and error (exception class instance or None)
    """
    try:
        # Resolve the HTTP method to the corresponding requests function
        method_name = method.lower()
        request_func = getattr(requests, method_name)
    except AttributeError:
        # Unsupported HTTP method
        return (None, ValueError(f"Unsupported HTTP method: {method}"))

    # Ensure the timeout is set (unless overridden by caller)
    kwargs.setdefault("timeout", timeout)

    try:
        # Send the request with provided arguments
        response = request_func(url, data=data, *args, **kwargs)
        # Return the status code; no exception is raised for HTTP error codes
        return (response.status_code, None)
    except requests.RequestException as exc:
        # Any requests-related exception (connection errors, timeouts, etc.)
        return (None, exc)
    except Exception as exc:
        # Catch-all for any other unexpected exceptions
        return (None, exc)

def dict_insert(dic, val, key, *keys):
    """insert a value of a nested key into a dictionary

    to insert value for a nested key, all ancestor keys should be given as
    method's arguments

    example:
      dict_insert({}, 'val', 'key1.key2'.split('.'))

    :param dic: a dictionary object to insert the nested key value into
    :param val: a value to insert to the given dictionary
    :param key: first key in a chain of key that will store the value
    :param keys: sub keys in the keys chain
    """
    try:
        if not isinstance(dic, dict):
            raise TypeError("dic must be a dictionary")

        # Handle case where the third argument itself is an iterable of keys
        if isinstance(key, (list, tuple)):
            all_keys = list(key)
        else:
            all_keys = [key] + list(keys)

        if not all_keys:
            raise ValueError("At least one key must be provided")

        # Navigate through the dictionary, creating sub‑dicts as needed
        current = dic
        for subkey in all_keys[:-1]:
            if not isinstance(subkey, (str, int, float, bytes, tuple, frozenset)):
                raise KeyError(f"Invalid key type: {type(subkey).__name__}")
            if subkey not in current or not isinstance(current[subkey], dict):
                current[subkey] = {}
            current = current[subkey]

        # Insert the value at the final key
        final_key = all_keys[-1]
        if not isinstance(final_key, (str, int, float, bytes, tuple, frozenset)):
            raise KeyError(f"Invalid key type: {type(final_key).__name__}")
        current[final_key] = val

        return dic
    except Exception as exc:
        # Re‑raise the exception with an informative message
        raise RuntimeError(f"Failed to insert value into dictionary: {exc}") from exc

def workspace_manager(cls):
        """Gets the workspace manager. """
        # Attempt to retrieve the workspace manager stored on the class.
        try:
            manager = getattr(cls, "_workspace_manager")
        except AttributeError:
            raise RuntimeError("Workspace manager is not configured for this class.")
        # If the manager is explicitly set to None, raise an error.
        if manager is None:
            raise RuntimeError("Workspace manager has not been initialized.")
        return manager

def plugins_manager(cls):
        """Gets the plugin manager."""
        # Enumerate potential attribute names that may hold the plugin manager.
        candidate_attrs = ("plugin_manager", "_plugin_manager", "plugins_manager")
        for attr in candidate_attrs:
            if hasattr(cls, attr):
                try:
                    manager = getattr(cls, attr)
                    if manager is not None:
                        return manager
                except Exception as exc:
                    raise RuntimeError(
                        f"Error accessing plugin manager attribute '{attr}' on {cls.__name__}: {exc}"
                    ) from exc
        # If none found, inform the caller.
        raise RuntimeError(f"Plugin manager not found on class {cls.__name__}.")

def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources."""
    defaults = {}
    try:
        # Extract the specification dictionary
        spec = getattr(self, "spec", {})
        if not isinstance(spec, dict):
            return defaults

        # Gather default values defined in the spec
        for arg_name, arg_entry in spec.items():
            # If the spec entry is a dict, look for a 'default' key
            if isinstance(arg_entry, dict):
                default_val = arg_entry.get("default")
            else:
                # If the entry is not a dict, treat the entry itself as the default
                default_val = arg_entry
            if default_val is not None:
                defaults[arg_name] = default_val

        # Merge with any additional sources that may be defined on the instance
        # (e.g., configuration files, environment overrides, etc.)
        if hasattr(self, "other_sources"):
            for key, val in getattr(self, "other_sources", {}).items():
                defaults.setdefault(key, val)
    except Exception:
        # If any unexpected issue occurs, fall back to an empty defaults dict
        defaults = {}
    return defaults

def get_deprecated_args(self):
    """
    Return a dictionary mapping deprecated option names to their current equivalents.
    Keys are deprecated configuration keys; values are the new keys that should be used.
    This method can be overridden by subclasses to provide library‑specific deprecations.
    """
    try:
        # Example mappings – these can be updated as the configuration evolves.
        deprecated_to_current = {
            'verbose': 'verbose_level',
            'quiet': 'log_level',
            'debug': 'log_level',
            'mode': 'operation_mode',
            'config_path': 'configuration_file',
        }
        return deprecated_to_current
    except Exception:
        # In case an unexpected error occurs, return an empty mapping to avoid breaking the caller.
        return {}

def validate_arg_deprecation(self, cli_args, answer_file_args):
    """
    Validates and prints the deprecated arguments.

    :param cli_args: the dict of arguments from cli
    :param answer_file_args:  the dict of arguments from files
    """
    import sys

    # Basic type validation
    if not isinstance(cli_args, dict):
        raise TypeError(f"cli_args must be a dict, got {type(cli_args).__name__}")
    if not isinstance(answer_file_args, dict):
        raise TypeError(f"answer_file_args must be a dict, got {type(answer_file_args).__name__}")

    # Retrieve deprecated arguments mapping
    # Supports either an iterable of old names or a mapping old->new
    deprecated = getattr(self, "deprecated_args", None)
    if not deprecated:
        return  # nothing to check

    # Normalize to list of tuples (old_name, new_name)
    if isinstance(deprecated, dict):
        deprecated_items = list(deprecated.items())
    else:
        try:
            deprecated_items = [(arg, None) for arg in deprecated]
        except TypeError:
            raise TypeError(
                "deprecated_args must be a dict or an iterable of argument names"
            )

    # Helper to format warning message
    def _format_msg(arg, new, source):
        msg = f"Argument '{arg}' from {source} is deprecated."
        if new:
            msg += f" Use '{new}' instead."
        return msg

    # Check CLI arguments
    for old_arg, new_arg in deprecated_items:
        if old_arg in cli_args:
            sys.stderr.write(_format_msg(old_arg, new_arg, "CLI") + "\n")

    # Check answer file arguments
    for old_arg, new_arg in deprecated_items:
        if old_arg in answer_file_args:
            sys.stderr.write(_format_msg(old_arg, new_arg, "answer file") + "\n")

def _get_conditionally_required_args(self, command_name, options_spec,
                                         args):
    """List arguments with ``required_when`` condition matched.

    :param command_name: the command name.
    :param options_spec:  the list of command spec options.
    :param args: the received input arguments
    :return: list, list of argument names with matched ``required_when``
        condition
    """
    condition_args = []
    # Basic sanity checks
    if not isinstance(command_name, str):
        return condition_args
    if not isinstance(options_spec, (list, tuple)):
        return condition_args

    for opt in options_spec:
        try:
            if not isinstance(opt, dict):
                continue
            name = opt.get("name")
            if not name:
                continue
            req_when = opt.get("required_when")
            if req_when is None:
                continue

            # Handle different possible shapes of required_when
            if isinstance(req_when, list):
                # A list of command names
                if command_name in req_when:
                    condition_args.append(name)
            elif isinstance(req_when, dict):
                # Mapping command name -> condition
                if command_name in req_when:
                    cond = req_when[command_name]
                    if isinstance(cond, bool):
                        if cond:
                            condition_args.append(name)
                    elif isinstance(cond, str):
                        # Assume the string is the name of an argument that must be present
                        if cond in args:
                            condition_args.append(name)
                    elif callable(cond):
                        try:
                            if cond(args):
                                condition_args.append(name)
                        except Exception:
                            pass
            elif isinstance(req_when, bool):
                if req_when:
                    condition_args.append(name)
            elif isinstance(req_when, str):
                # Simple requirement that a specific arg name must be present
                if req_when in args:
                    condition_args.append(name)
        except Exception:
            # Skip malformed option entries
            continue

    # Preserve order but remove duplicates
    seen = set()
    unique_args = []
    for a in condition_args:
        if a not in seen:
            seen.add(a)
            unique_args.append(a)

    return unique_args

def create_complex_argumet_type(self, subcommand, type_name, option_name,
                                    spec_option):
        """
        Build the complex argument type

        :param subcommand: the command name
        :param type_name: the complex type name
        :param option_name: the option name
        :param spec_option: option's specifications
        :return: the complex type instance (dict)
        """
        try:
            # Basic type validation
            if not isinstance(subcommand, str):
                raise TypeError(f"subcommand must be a str, got {type(subcommand).__name__}")
            if not isinstance(type_name, str):
                raise TypeError(f"type_name must be a str, got {type(type_name).__name__}")
            if not isinstance(option_name, str):
                raise TypeError(f"option_name must be a str, got {type(option_name).__name__}")

            # Convert spec_option to a dict if possible
            spec_dict = None
            if spec_option is None:
                spec_dict = {}
            else:
                if isinstance(spec_option, dict):
                    spec_dict = spec_option
                else:
                    try:
                        spec_dict = dict(spec_option)
                    except Exception:
                        # If conversion fails, fall back to the original
                        spec_dict = spec_option

            complex_type = {
                "subcommand": subcommand,
                "type_name": type_name,
                "option_name": option_name,
                "spec_option": spec_dict
            }
            return complex_type
        except Exception as exc:
            # Wrap any unexpected error in a RuntimeError to avoid exposing internal details
            raise RuntimeError(f"Failed to create complex argument type: {exc}") from exc

def ansible_playbook(ir_workspace, ir_plugin, playbook_path, verbose=None,
                     extra_vars=None, ansible_args=None):
    """
    Wraps the 'ansible-playbook' CLI.

    :param ir_workspace: An Infrared Workspace object represents the active
        workspace
    :param ir_plugin: An InfraredPlugin object of the current plugin
    :param playbook_path: the playbook to invoke
    :param verbose: Ansible verbosity level (int)
    :param extra_vars: dict. Passed to Ansible as extra-vars
    :param ansible_args: dict of ansible-playbook arguments to plumb down
        directly to Ansible.
    :return: The subprocess.CompletedProcess instance returned by the playbook run.
    """
    import subprocess
    import json
    import shlex

    # Base command
    cmd = ["ansible-playbook", playbook_path]

    # Add verbosity
    if isinstance(verbose, int) and verbose > 0:
        cmd.extend(["-v"] * verbose)

    # Add any explicit ansible arguments
    if isinstance(ansible_args, dict):
        for key, value in ansible_args.items():
            # Determine flag string
            flag = key
            if not flag.startswith("-"):
                flag = f"--{flag}"
            if isinstance(value, bool):
                if value:
                    cmd.append(flag)
            elif isinstance(value, (list, tuple)):
                for val in value:
                    cmd.extend([flag, str(val)])
            else:
                # For None or False we skip
                if value is not None and value is not False:
                    cmd.extend([flag, str(value)])

    # Add extra-vars
    if isinstance(extra_vars, dict) and extra_vars:
        try:
            json_str = json.dumps(extra_vars)
        except Exception as exc:
            raise ValueError(f"Failed to serialize extra_vars: {exc}") from exc
        cmd.extend(["--extra-vars", json_str])

    # Execute command
    try:
        # Use stdout/stderr capture to avoid dropping output
        result = subprocess.run(
            cmd,
            cwd=ir_workspace.path if hasattr(ir_workspace, "path") else None,
            capture_output=True,
            text=True,
            check=False,
        )
    except FileNotFoundError as exc:
        raise RuntimeError("The 'ansible-playbook' command was not found.") from exc
    except Exception as exc:
        raise RuntimeError(f"An error occurred while running ansible-playbook: {exc}") from exc

    # Log output if plugin provides a logging method
    log_method = getattr(ir_plugin, "LOG", None)
    if callable(log_method):
        if result.stdout:
            log_method("[Ansible stdout]\n" + result.stdout)
        if result.stderr:
            log_method("[Ansible stderr]\n" + result.stderr)

    if result.returncode != 0:
        raise RuntimeError(
            f"Ansible playbook exited with code {result.returncode}:\n"
            f"stdout: {result.stdout}\nstderr: {result.stderr}"
        )

    return result

def _convert_non_cli_args(self, parser_name, values_dict):
    """Casts arguments to correct types by modifying values_dict param.

    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict of with arguments
    :return: The same dictionary with values cast to appropriate types
    """
    if not isinstance(values_dict, dict):
        raise TypeError("values_dict must be a dictionary")

    # Helper sets for simple type checks
    bool_true = {"true", "1", "yes", "on"}
    bool_false = {"false", "0", "no", "off"}

    for key, raw_val in list(values_dict.items()):
        try:
            if isinstance(raw_val, str):
                val = raw_val.strip()
                lowered = val.lower()

                # Boolean conversion
                if lowered in bool_true:
                    values_dict[key] = True
                    continue
                if lowered in bool_false:
                    values_dict[key] = False
                    continue

                # Integer conversion (handles decimal, hex, octal, binary)
                try:
                    if val.lower().startswith(("0x", "-0x", "0b", "-0b", "0o", "-0o")):
                        values_dict[key] = int(val, 0)
                    else:
                        values_dict[key] = int(val)
                    continue
                except ValueError:
                    pass

                # Float conversion
                try:
                    values_dict[key] = float(val)
                    continue
                except ValueError:
                    pass

                # List conversion: comma-separated values become a list
                if "," in val:
                    # Preserve surrounding spaces by stripping each item
                    values_dict[key] = [item.strip() for item in val.split(",")]
                    continue

                # If nothing matched, leave as string
            else:
                # Non-string types are left as is (or subclassed types are fine)
                continue
        except Exception as exc:
            # Log the exception if logger is available; otherwise ignore and keep original
            if hasattr(self, 'logger'):
                try:
                    self.logger.error(
                        f"Error converting key '{key}' with value '{raw_val}': {exc}"
                    )
                except Exception:
                    pass
            # Keep the original value untouched if conversion fails

    return values_dict

def inject_config(self):
    """Set the environment variable for config path, if it is undefined."""
    import os
    key = "CONFIG_PATH"
    try:
        if os.environ.get(key) is None:
            # Default path: config.yml in current working directory
            default_path = os.path.join(os.getcwd(), "config.yml")
            os.environ[key] = default_path
    except Exception as exc:
        raise RuntimeError(f"Unable to set environment variable '{key}': {exc}") from exc
